window.AUTH=window.AUTH||{};window.AUTH["25-5930"]={"d":"25-5930","id":"2026/25-5930","n":"Maxwell v. Dinis","briefs":[{"k":"petitioner","label":"Brief of petitioner William Maxwell","date":"2026-08-05","url":"https://www.supremecourt.gov/DocketPDF/25/25-5930/418167/20260805123041240_25-5930%20opening%20brief%20final_PDFA.pdf","side":"pet","n":131},{"k":"respondent","label":"Brief for the respondent Sandra Dinis, Acting Warden supporting vacatur","date":"2026-08-05","url":"https://www.supremecourt.gov/DocketPDF/25/25-5930/418232/20260805174545194_25-5930UnitedStates.pdf","side":"res","n":144},{"k":"reply","label":"Reply of petitioner William Maxwell","date":"2026-10-19","url":"https://www.supremecourt.gov/DocketPDF/25/25-5930/429966/20261019143126980_25-5930MaxwellReplyBrief.pdf","side":"pet","n":65}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"sum":"The Court found that a defendant cannot be found guilty of a claim not included in the indictment.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Alqsous v. Emmerich","cite":"2026 WL 125691","y":2026,"court":"W.D. Wis. Jan. 16","by":{"0":"36"}},{"t":"case","label":"Andreozzi v. Manager, Residential Reentry Management Seattle","cite":"2023 WL 7156173","y":2023,"court":"W.D. Wash. Oct. 31","by":{"0":"35"}},{"t":"case","label":"Arketa v. Wilson","cite":"373 F.2d 582","y":1967,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/373/582/","by":{"0":"24"}},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Beras v. Johnson","cite":"978 F.3d 246","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/978/246/","by":{"0":"32"}},{"t":"case","label":"Bivens v. Six Unknown Federal Narcotics Agents","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"ar":6,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"11, 13, 30, 38","1":"2, 13, 15, 20","2":"14"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"5, 6"}},{"t":"case","label":"Bowe v. United States","cite":"607 U.S. 13","y":2026,"id":"2025/24-5438","sc":1,"sum":"Title 28 U. S. C. §2244(b)(3)(E) does not bar this Court’s review of a federal prisoner’s request to file a second or successive §2255 motion for postconviction relief, and §2244(b)(1) does not apply to second or successive motions filed under §2255(h) by federal prisoners challenging their convictions or sentences.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7, 32"}},{"t":"case","label":"Boyce v. Ashcroft","cite":"251 F.3d 911","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/251/911/","by":{"0":"38"}},{"t":"case","label":"Brown v. Davenport","cite":"596 U.S. 118","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7","1":"17, 19, 39"}},{"t":"case","label":"Brown-El v. Hall","cite":"8 F.3d 20","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/8/20/","by":{"0":"36"}},{"t":"case","label":"Butler v. United States Parole Commission","cite":"570 F. Supp. 67","y":1983,"court":"M.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./570/67/","by":{"0":"36"}},{"t":"case","label":"Carafas v. LaVallee","cite":"391 U.S. 234","y":1968,"id":"1967/71","sc":1,"sum":"In 1960 petitioner was convicted in New York state criminal proceedings and his sentence was affirmed on appeal without opinion over his contention that illegally obtained evidence had been introduced against him at his trial. Renewing that claim, petitioner thereafter sought relief in the federal and state courts by writ of habeas corpus. The petition in the present case was filed in June 1963, while petitioner was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Carmona v. United States Bureau of Prisons","cite":"243 F.3d 629","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/243/629/","by":{"0":"32","1":"35"}},{"t":"case","label":"Cheney v. United States District Court for District of Columbia","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"31","1":"34"}},{"t":"case","label":"Cisco Systems, Inc. v. Doe I","cite":"146 S. Ct. 1882","y":2026,"id":"2025/24-856","sc":1,"sum":"The Court held that neither the Alien Tort Statute nor the Torture Victim Protection Act supplies a judicially implied private right of action for aiding-and-abetting liability.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Cofer v. Fleming","cite":"2001 WL 1297687","y":2001,"court":"N.D. Tex. Oct. 11","by":{"0":"36"}},{"t":"case","label":"Coleman v. Tennessee","cite":"97 U.S. 509","y":1878,"id":"scdb/1878-108","sc":1,"by":{"0":"22, 23"}},{"t":"case","label":"Correctional Services Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"30","1":"20"}},{"t":"case","label":"Cossio v. Air Force Court of Criminal Appeals","cite":"129 F.4th 1013","y":2025,"url":"https://www.courtlistener.com/c/F.4th/129/1013/","by":{"0":"40"}},{"t":"case","label":"Department of Homeland Security v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"id":"2019/19-161","sc":1,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30","1":"33"}},{"t":"case","label":"Escoe v. Zerbst","cite":"295 U.S. 490","y":1935,"id":"scdb/1934-133","sc":1,"by":{"0":"23, 24"}},{"t":"case","label":"Falcon v. United States Bureau of Prisons","cite":"52 F.3d 137","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/52/137/","by":{"0":"39"}},{"t":"case","label":"Federal Defenders of New York, Inc. v. Federal Bureau of Prisons","cite":"954 F.3d 118","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/954/118/","by":{"0":"31"}},{"t":"case","label":"Finetti v. Harris","cite":"609 F.2d 594","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/609/594/","by":{"0":"24"}},{"t":"case","label":"Fortner v. Eischen","cite":"170 F.4th 655","y":2026,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/170/655/","by":{"0":"30, 37, 39, 40","1":"27, 29","2":"7"}},{"t":"case","label":"Fuller v. Rich","cite":"11 F.3d 61","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/11/61/","by":{"0":"32"}},{"t":"case","label":"Ganim v. Federal Bureau of Prisons","cite":"235 Fed. Appx. 882","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./235/882/","by":{"0":"39"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"sum":"The Court held that individuals held in military confinement by the national government have a right, under the Fifth Amendment, to appeal that confinement in front of a neutral decision-making body.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Hensley v. Municipal Court","cite":"411 U.S. 345","y":1973,"id":"1972/71-1428","sc":1,"sum":"Restraints imposed on petitioner who was released on his own recognizance constitute \"custody\" within the meaning of the federal habeas corpus statute, 28 U. S. C. §§2241 (c) (3), 2254 (a). Pp. 348-353. 453 F. 2d 1252, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 40","1":"30"}},{"t":"case","label":"Hill v. McDonough","cite":"547 U.S. 573","y":2006,"id":"2005/05-8794","sc":1,"sum":"The Supreme Court held that challenging the form of execution was fundamentally different from challenging the lawfulness of a conviction or sentence, the traditional purposes of a habeas corpus appeal.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Hilton v. Braunskill","cite":"481 U.S. 770","y":1987,"id":"1986/86-108","sc":1,"sum":"In deciding under Rules 23(c) and (d) whether to stay pending appeal a district court order granting relief to a habeas petitioner, federal courts are not restricted to considering only the petitioner's risk of flight. The history of federal habeas corpus practice indicates that a court has broad discretion in conditioning a judgment granting habeas relief, and a court's denial of enlargement to a successful habeas …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Jones v. Cunningham","cite":"371 U.S. 236","y":1963,"id":"1962/77","sc":1,"ar":1,"sum":"1. A state prisoner who has been placed on parole, under the \"custody and control\" of a parole board, is \"in custody\" within the meaning of 28 U. S. C. § 2241; and, on his petition for a writ of habeas corpus, a Federal District. Court has jurisdiction to hear and determihe his charge that his state sentence was imposed in violation of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 26, 40","1":"15, 27, 28, 30"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"ar":1,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7, 12, 18, 19, 27, 28, 32","1":"13, 17-19, 24, 27, 30, 39","2":"5, 7"}},{"t":"case","label":"Joost v. United States Parole Commission","cite":"698 F.2d 418","y":1983,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/698/418/","by":{"0":"24"}},{"t":"case","label":"Justices of Boston Municipal Court v. Lydon","cite":"466 U.S. 294","y":1984,"id":"1983/82-1479","sc":1,"sum":"Under Massachusetts law, a defendant charged with certain minor crimes in Boston Municipal Court may elect to have a bench trial or a jury trial. If he chooses a jury trial and is convicted, he has the normal appellate process open to him, but if he chooses a bench trial and is dissatisfied with the results, he has an absolute right to a trial de novo before a jury and need not allege error at the bench trial to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Khalil v. President","cite":"164 F.4th 259","y":2026,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/164/259/","by":{"0":"32"}},{"t":"case","label":"Klein v. Martin","cite":"607 U.S. 213","y":2026,"url":"https://supreme.justia.com/cases/federal/us/607/213/","sc":1,"by":{"0":"7"}},{"t":"case","label":"Kruger v. Erickson","cite":"77 F.3d 1071","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/77/1071/","by":{"0":"39"}},{"t":"case","label":"Mahler v. Eby","cite":"264 U.S. 32","y":1924,"id":"scdb/1923-058","sc":1,"sum":"1. The inhibition of ex post facto laws, (Const. Art. I, § 9) applies only to criminal laws, and not to a law for deporting aliens who by conviction of crime are shown to be undesirable as residents of this country.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Mandacina v. Entzel","cite":"991 F.3d 758","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/758/","by":{"0":"33"}},{"t":"case","label":"Martin v. Solem","cite":"801 F.2d 324","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/801/324/","by":{"0":"24"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"McDonough v. Smith","cite":"588 U.S. 109","y":2019,"id":"2018/18-485","sc":1,"sum":"The Court held that the statute of limitations for the petitioner’s § 1983 fabricated evidence claim began to run when the criminal proceedings against him terminated in his favor—that is, when he was acquitted at the end of his second trial.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"McMiller v. Carter","cite":"2025 WL 3022385","y":2025,"court":"D. Md. Oct. 29","sum":"Holding an APA suit raising a First Step Act claim barred by Section 3625.","sumSrc":"brief:0","by":{"0":"31"}},{"t":"case","label":"Melot v. Bergami","cite":"970 F.3d 596","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/970/596/","sum":"Noting a contrary nonprecedential Fifth Circuit decision.","sumSrc":"brief:1","by":{"0":"11, 30, 37, 38","1":"13, 32"}},{"t":"case","label":"Minnesota v. Murphy","cite":"465 U.S. 420","y":1984,"id":"1983/82-827","sc":1,"sum":"The Supreme Court held that admissions made to a probation officer about a crime unrelated to the probation are admissible in subsequent prosecution. A state may require a probationer to meet with his officer and discuss matters that may affect his probationary status, but this does not create an exception to the rule that one must assert the privilege against self-incrimination.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Mont v. United States","cite":"587 U.S. 514","y":2019,"id":"2018/17-8995","sc":1,"sum":"Pretrial detention later credited as time served for a new conviction tolls a supervised-release term under 18 U. S. C. §3624(e), even if the court must make the tolling calculation after learning whether the time will be credited.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"8","1":"31"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Nance v. Ward","cite":"597 U.S. 159","y":2022,"id":"2021/21-439","sc":1,"sum":"Title 42 U. S. C. §1983 is the procedural vehicle appropriate for a prisoner’s method-of-execution claim even if an order granting the relief requested would necessitate a change in state law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28, 38"}},{"t":"case","label":"Nekvasil v. United States","cite":"2022 WL 4115428","y":2022,"court":"W.D. Mich. Sept. 9","by":{"0":"35"}},{"t":"case","label":"Olivier v. City of Brandon","cite":"607 U.S. 552","y":2026,"id":"2025/24-993","sc":1,"sum":"Petitioner Gabriel Olivier’s suit seeking purely prospective relief—an injunction stopping officials from enforcing an ordinance in the future—can proceed, notwithstanding his prior conviction for violating that ordinance; Heck v. Humphrey, 512 U. S. 477 (1994), does not hold otherwise.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40","1":"21, 25"}},{"t":"case","label":"Ortega v. United States Immigration & Customs Enforcement","cite":"737 F.3d 435","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/737/435/","by":{"0":"36"}},{"t":"case","label":"Palma-Salazar v. Davis","cite":"677 F.3d 1031","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/677/1031/","by":{"0":"38"}},{"t":"case","label":"Peyton v. Rowe","cite":"391 U.S. 54","y":1968,"id":"1967/802","sc":1,"sum":"A prisoner serving consecutive sentences is \"in custody\" under any one of them for purposes of § 2241 (c) (3) and may in a federal habeas corpus proceeding thereunder challenge the constitutionality of a sentence scheduled for futur6 service. The decision in McNally v. Hill, supra, which was compelled neither by statute nor history and which constitutes an indefensible barrier to prompt adjudication of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"17, 28"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"ar":13,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 13, 15, 17, 25-27, 33, 34, 36","1":"3, 14, 17, 18, 21-23, 25, 28, 30, 39","2":"5, 6, 10"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29","1":"8"}},{"t":"case","label":"Rasul v. Bush","cite":"542 U.S. 466","y":2004,"id":"2003/03-334","sc":1,"sum":"The Court ruled that United States courts have jurisdiction to consider legal appeals filed on behalf of foreign citizens held by the United States military in Guantanamo Bay Naval Base, Cuba.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"RJR Nabisco v. European Community","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Rodriguez v. McGinnis","cite":"307 F. Supp. 627","y":1969,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./307/627/","by":{"0":"25"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"sum":"Instead, in 5-to-4 opinion written by Chief Justice William H. Rehnquist, the Court found that the case had been improperly filed. Under federal law, a petition for a writ of habeas corpus can only be filed against the person directly responsible for a prisoner's confinement or, put another way, the person with the power to bring the prisoner to court.","sumSrc":"Oyez","by":{"0":"17, 32, 35","2":"10"}},{"t":"case","label":"Samak v. Warden, FCC Coleman-Medium","cite":"766 F.3d 1271","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/766/1271/","by":{"0":"28","2":"18, 19"}},{"t":"case","label":"Schonbrun v. Commanding Officer, Armed Forces","cite":"403 F.2d 371","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/403/371/","by":{"0":"24"}},{"t":"case","label":"Seymore v. Beto","cite":"383 F.2d 384","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/383/384/","by":{"0":"24"}},{"t":"case","label":"Skinner v. Switzer","cite":"562 U.S. 521","y":2011,"id":"2010/09-9000","sc":1,"ar":3,"sum":"The Court held that a convicted prisoner seeking access to biological evidence for DNA testing may assert that claim in a civil rights action under 42 U.S.C. § 1983.","sumSrc":"Oyez","by":{"0":"3, 27, 33","1":"24","2":"4, 6"}},{"t":"case","label":"Solida v. McKelvey","cite":"820 F.3d 1090","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/820/1090/","by":{"0":"30"}},{"t":"case","label":"Spencer v. Haynes","cite":"774 F.3d 467","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/774/467/","by":{"0":"30, 39"}},{"t":"case","label":"Storm v. United States Parole Commission","cite":"667 Fed. Appx. 156","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./667/156/","by":{"0":"36"}},{"t":"case","label":"Thomas v. Brennan","cite":"961 F.2d 612","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/961/612/","by":{"0":"24"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"sum":"Because universal injunctions likely exceed the equitable authority that Congress has granted to federal courts, the Court grants the Government’s applications for a partial stay of the injunctions entered below regarding the implementation and enforcement of President Trump’s Executive Order No. 14160, but only to the extent that the injunctions are broader than necessary to provide complete relief to each plaintiff with standing to sue.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"31"}},{"t":"case","label":"Trump v. Cook","cite":"146 S. Ct. 2234","y":2026,"url":"https://www.courtlistener.com/c/S.%20Ct./146/2234/","sc":1,"by":{"0":"31"}},{"t":"case","label":"Trump v. J.G.G.","cite":"604 U.S. 670","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/670/","sc":1,"by":{"0":"18, 28, 29, 32","2":"5"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"sum":"The District Court erred in determining the factual issues raised by respondent's motion under § 2255 without notice to respondent and without his presence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 33"}},{"t":"case","label":"United States v. Haymond","cite":"588 U.S. 634","y":2019,"id":"2018/17-1672","sc":1,"sum":"The Tenth Circuit’s judgment—that 18 U. S. C. §3583(k)’s last two sentences are unconstitutional and unenforceable—is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7"}},{"t":"case","label":"United States v. Jones","cite":"752 F.3d 1039","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/752/1039/","by":{"0":"36"}},{"t":"case","label":"United States v. Scarfo","cite":"41 F.4th 136","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/41/136/","by":{"0":"9"}},{"t":"case","label":"Valladares v. Ray","cite":"130 F.4th 74","y":2025,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/130/74/","by":{"0":"9"}},{"t":"case","label":"Walker v. Wainwright","cite":"390 U.S. 335","y":1968,"id":"scdb/1967-079","sc":1,"sum":"Whatever its other functions, the writ of habeas corpus is available to test the legality of a prisoner's current detention, and it is immaterial that another prison term might await him if he should establish the unconstitutionality of his present imprisonment. Certiorari granted; reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Wilkinson v. Dotson","cite":"544 U.S. 74","y":2005,"id":"2004/03-287","sc":1,"sum":"Yes and No. In an 8-1 decision, the Court affirmed the appellate court and ruled that prisoners could use Section 1983 to challenge a state's parole procedures.","sumSrc":"Oyez","by":{"0":"3, 6, 18, 26, 27, 38","1":"3, 20, 23-26, 28, 34","2":"6, 7"}},{"t":"case","label":"Woodall v. Federal Bureau of Prisons","cite":"432 F.3d 235","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/432/235/","by":{"0":"36","1":"31, 32"}},{"t":"case","label":"Page Case—continued: Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/120/","sc":1,"by":{"0":"30"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"0":"6","2":"18, 19"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"13, 30, 31, 33","1":"21"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"7, 14, 32, 33","1":"19"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"9, 10, 11, 31, 34","1":"2, 8","2":"7-10, 17-19"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"8","2":"13"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(b)","(b)(11)","(b)(19)"],"by":{"0":"9, 36, 36"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(d)","(e)(3)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"8, 8, 8, 9","1":"7, 8, 32"}},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(c)","(c)(1)","(g)","(g)(2)(A)(i)","(g)(2)(A)(i)(II)","(g)(2)(B)","(g)(4)","(g)(5)","(a)","(b)(1)","(c)(2)","(c)(4)","(c)(5)","(g)(1)","(g)(1)(A)","(g)(1)(B)","(g)(2)","(g)(2)(A)","(g)(2)(A)(i)(I)","(g)(3)","(g)(10)","(g)(2)(A)(i)(II)(gg)"],"stext":{"head":"§3624. Release of a prisoner","paras":[[0,"(a) Date of Release.—A prisoner shall be released by the Bureau of Prisons on the date of the expiration of the prisoner's term of imprisonment, less any time credited toward the service of the prisoner's sentence as provided in subsection (b). If the date for a prisoner's release falls on a Saturday, a Sunday, or a legal holiday at the place of confinement, the prisoner may be released by the Bureau on the last preceding weekday."],[0,"(b) Credit Toward Service of Sentence for Satisfactory Behavior.—(1) Subject to paragraph (2), a prisoner who is serving a term of imprisonment of more than 1 year 1 other than a term of imprisonment for the duration of the prisoner's life, may receive credit toward the service of the prisoner's sentence of up to 54 days for each year of the prisoner's sentence imposed by the court, subject to determination by the Bureau of Prisons that, during that year, the prisoner has displayed exemplary compliance with institutional disciplinary regulations. Subject to paragraph (2), if the Bureau determines that, during that year, the prisoner has not satisfactorily complied with such institutional regulations, the prisoner shall receive no such credit toward service of the prisoner's sentence or shall receive such lesser credit as the Bureau determines to be appropriate. In awarding credit under this section, the Bureau shall consider whether the prisoner, during the relevant period, has earned, or is making satisfactory progress toward earning, a high school diploma or an equivalent degree. Credit that has not been earned may not later be granted. Subject to paragraph (2), credit for the last year of a term of imprisonment shall be credited on the first day of the last year of the term of imprisonment."],[0,"(2) Notwithstanding any other law, credit awarded under this subsection after the date of enactment of the Prison Litigation Reform Act shall vest on the date the prisoner is released from custody."],[0,"(3) The Attorney General shall ensure that the Bureau of Prisons has in effect an optional General Educational Development program for inmates who have not earned a high school diploma or its equivalent."],[0,"(4) Exemptions to the General Educational Development requirement may be made as deemed appropriate by the Director of the Federal Bureau of Prisons."],[0,"(c) Prerelease Custody.—"],[1,"(1) In general.—The Director of the Bureau of Prisons shall, to the extent practicable, ensure that a prisoner serving a term of imprisonment spends a portion of the final months of that term (not to exceed 12 months), under conditions that will afford that prisoner a reasonable opportunity to adjust to and prepare for the reentry of that prisoner into the community. Such conditions may include a community correctional facility."],[1,"(2) Home confinement authority.—The authority under this subsection may be used to place a prisoner in home confinement for the shorter of 10 percent of the term of imprisonment of that prisoner or 6 months. The Bureau of Prisons shall, to the extent practicable, place prisoners with lower risk levels and lower needs on home confinement for the maximum amount of time permitted under this paragraph."],[1,"(3) Assistance.—The United States Probation System shall, to the extent practicable, offer assistance to a prisoner during prerelease custody under this subsection."],[1,"(4) No limitations.—Nothing in this subsection shall be construed to limit or restrict the authority of the Director of the Bureau of Prisons under section 3621."],[1,"(5) Reporting.—Not later than 1 year after the date of the enactment of the Second Chance Act of 2007 (and every year thereafter), the Director of the Bureau of Prisons shall transmit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report describing the Bureau's utilization of community corrections facilities. Each report under this paragraph shall set forth the number and percentage of Federal prisoners placed in community corrections facilities during the preceding year, the average length of such placements, trends in such utilization, the reasons some prisoners are not placed in community corrections facilities, and number of prisoners not being placed in community corrections facilities for each reason set forth, and any other information that may be useful to the committees in determining if the Bureau is utilizing community corrections facilities in an effective manner."],[1,"(6) Issuance of regulations.—The Director of the Bureau of Prisons shall issue regulations pursuant to this subsection not later than 90 days after the date of the enactment of the Second Chance Reauthorization Act of 2018, which shall ensure that placement in a community correctional facility by the Bureau of Prisons is—"],[2,"(A) conducted in a manner consistent with section 3621(b) of this title;"],[2,"(B) determined on an individual basis; and"],[2,"(C) of sufficient duration to provide the greatest likelihood of successful reintegration into the community."],[0,"(d) Allotment of Clothing, Funds, and Transportation.—Upon the release of a prisoner on the expiration of the prisoner's term of imprisonment, the Bureau of Prisons shall furnish the prisoner with—"],[1,"(1) suitable clothing;"],[1,"(2) an amount of money, not more than $500, determined by the Director to be consistent with the needs of the offender and the public interest, unless the Director determines that the financial position of the offender is such that no sum should be furnished; and"],[1,"(3) transportation to the place of the prisoner's conviction, to the prisoner's bona fide residence within the United States, or to such other place within the United States as may be authorized by the Director."],[0,"(e) Supervision After Release.—A prisoner whose sentence includes a term of supervised release after imprisonment shall be released by the Bureau of Prisons to the supervision of a probation officer who shall, during the term imposed, supervise the person released to the degree warranted by the conditions specified by the sentencing court. The term of supervised release commences on the day the person is released from imprisonment and runs concurrently with any Federal, State, or local term of probation or supervised release or parole for another offense to which the person is subject or becomes subject during the term of supervised release. A term of supervised release does not run during any period in which the person is imprisoned in connection with a conviction for a Federal, State, or local crime unless the imprisonment is for a period of less than 30 consecutive days. Upon the release of a prisoner by the Bureau of Prisons to supervised release, the Bureau of Prisons shall notify such prisoner, verbally and in writing, of the requirement that the prisoner adhere to an installment schedule, not to exceed 2 years except in special circumstances, to pay for any fine imposed for the offense committed by such prisoner, and of the consequences of failure to pay such fines under sections 3611 through 3614 of this title."],[0,"(f) Mandatory Functional Literacy Requirement.—"],[1,"(1) The Attorney General shall direct the Bureau of Prisons to have in effect a mandatory functional literacy program for all mentally capable inmates who are not functionally literate in each Federal correctional institution within 6 months from the date of the enactment of this Act."],[1,"(2) Each mandatory functional literacy program shall include a requirement that each inmate participate in such program for a mandatory period sufficient to provide the inmate with an adequate opportunity to achieve functional literacy, and appropriate incentives which lead to successful completion of such programs shall be developed and implemented."],[1,"(3) As used in this section, the term \"functional literacy\" means—"],[2,"(A) an eighth grade equivalence in reading and mathematics on a nationally recognized standardized test;"],[2,"(B) functional competency or literacy on a nationally recognized criterion-referenced test; or"],[2,"(C) a combination of subparagraphs (A) and (B)."],[1,"(4) Non-English speaking inmates shall be required to participate in an English-As-A-Second-Language program until they function at the equivalence of the eighth grade on a nationally recognized educational achievement test."],[1,"(5) The Chief Executive Officer of each institution shall have authority to grant waivers for good cause as determined and documented on an individual basis."],[0,"(g) Prerelease Custody or Supervised Release for Risk and Needs Assessment System Participants.—"],[1,"(1) Eligible prisoners.—This subsection applies in the case of a prisoner (as such term is defined in section 3635) who—"],[2,"(A) has earned time credits under the risk and needs assessment system developed under subchapter D (referred to in this subsection as the \"System\") in an amount that is equal to the remainder of the prisoner's imposed term of imprisonment;"],[2,"(B) has shown through the periodic risk reassessments a demonstrated recidivism risk reduction or has maintained a minimum or low recidivism risk, during the prisoner's term of imprisonment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3624?type=usc&year=mostrecent&link-type=html"},"head":"§3624. Release of a prisoner","tname":"Crimes and Criminal Procedure","by":{"0":"8, 9, 34, 34, 9, 14, 34, 36, 34, 34, 34, 35","1":"20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20","2":"9, 3, 13, 17, 18, 9, 18, 11, 9, 11, 9, 13"}},{"t":"usc","label":"18 U.S.C. § 3625","url":"https://www.law.cornell.edu/uscode/text/18/3625","stext":{"head":"§3625. Inapplicability of the Administrative Procedure Act","paras":[[0,"The provisions of sections 554 and 555 and 701 through 706 of title 5, United States Code, do not apply to the making of any determination, decision, or order under this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3625?type=usc&year=mostrecent&link-type=html"},"head":"§3625. Inapplicability of the Administrative Procedure Act","tname":"Crimes and Criminal Procedure","by":{"0":"31","1":"20"}},{"t":"usc","label":"18 U.S.C. § 3632","url":"https://www.law.cornell.edu/uscode/text/18/3632","subs":["(d)","(d)(4)(A)","(d)(4)(C)","(a)(3)","(d)(1)","(d)(4)(A)(i)","(d)(4)(D)","(d)(4)"],"stext":{"head":"§3632. Development of risk and needs assessment system","paras":[[0,"(a) In General.—Not later than 210 days after the date of enactment of this subchapter, the Attorney General, in consultation with the Independent Review Committee authorized by the First Step Act of 2018, shall develop and release publicly on the Department of Justice website a risk and needs assessment system (referred to in this subchapter as the \"System\"), which shall be used to—"],[1,"(1) determine the recidivism risk of each prisoner as part of the intake process, and classify each prisoner as having minimum, low, medium, or high risk for recidivism;"],[1,"(2) assess and determine, to the extent practicable, the risk of violent or serious misconduct of each prisoner;"],[1,"(3) determine the type and amount of evidence-based recidivism reduction programming that is appropriate for each prisoner and assign each prisoner to such programming accordingly, and based on the prisoner's specific criminogenic needs, and in accordance with subsection (b);"],[1,"(4) reassess the recidivism risk of each prisoner periodically, based on factors including indicators of progress, and of regression, that are dynamic and that can reasonably be expected to change while in prison;"],[1,"(5) reassign the prisoner to appropriate evidence-based recidivism reduction programs or productive activities based on the revised determination to ensure that—"],[2,"(A) all prisoners at each risk level have a meaningful opportunity to reduce their classification during the period of incarceration;"],[2,"(B) to address 1 the specific criminogenic needs of the prisoner; and"],[2,"(C) all prisoners are able to successfully participate in such programs;"],[1,"(6) determine when to provide incentives and rewards for successful participation in evidence-based recidivism reduction programs or productive activities in accordance with subsection (e);"],[1,"(7) determine when a prisoner is ready to transfer into prerelease custody or supervised release in accordance with section 3624; and"],[1,"(8) determine the appropriate use of audio technology for program course materials with an understanding of dyslexia."],[0,"In carrying out this subsection, the Attorney General may use existing risk and needs assessment tools, as appropriate."],[0,"(b) Assignment of Evidence-based Recidivism Reduction Programs.—The System shall provide guidance on the type, amount, and intensity of evidence-based recidivism reduction programming and productive activities that shall be assigned for each prisoner, including—"],[1,"(1) programs in which the Bureau of Prisons shall assign the prisoner to participate, according to the prisoner's specific criminogenic needs; and"],[1,"(2) information on the best ways that the Bureau of Prisons can tailor the programs to the specific criminogenic needs of each prisoner so as to most effectively lower each prisoner's risk of recidivism."],[0,"(c) Housing and Assignment Decisions.—The System shall provide guidance on program grouping and housing assignment determinations and, after accounting for the safety of each prisoner and other individuals at the prison, provide that prisoners with a similar risk level be grouped together in housing and assignment decisions to the extent practicable."],[0,"(d) Evidence-Based Recidivism Reduction Program Incentives and Productive Activities Rewards.—The System shall provide incentives and rewards for prisoners to participate in and complete evidence-based recidivism reduction programs as follows:"],[1,"(1) Phone and visitation privileges.—A prisoner who is successfully participating in an evidence-based recidivism reduction program shall receive—"],[2,"(A) phone privileges, or, if available, video conferencing privileges, for up to 30 minutes per day, and up to 510 minutes per month; and"],[2,"(B) additional time for visitation at the prison, as determined by the warden of the prison."],[1,"(2) Transfer to institution closer to release residence.—A prisoner who is successfully participating in an evidence-based recidivism reduction program shall be considered by the Bureau of Prisons for placement in a facility closer to the prisoner's release residence upon request from the prisoner and subject to—"],[2,"(A) bed availability at the transfer facility;"],[2,"(B) the prisoner's security designation; and"],[2,"(C) the recommendation from the warden of the prison at which the prisoner is incarcerated at the time of making the request."],[1,"(3) Additional policies.—The Director of the Bureau of Prisons shall develop additional policies to provide appropriate incentives for successful participation and completion of evidence-based recidivism reduction programming. The incentives shall include not less than 2 of the following:"],[2,"(A) Increased commissary spending limits and product offerings."],[2,"(B) Extended opportunities to access the email system."],[2,"(C) Consideration of transfer to preferred housing units (including transfer to different prison facilities)."],[2,"(D) Other incentives solicited from prisoners and determined appropriate by the Director."],[1,"(4) Time credits.—"],[2,"(A) In general.—A prisoner, except for an ineligible prisoner under subparagraph (D), who successfully completes evidence-based recidivism reduction programming or productive activities, shall earn time credits as follows:"],[3,"(i) A prisoner shall earn 10 days of time credits for every 30 days of successful participation in evidence-based recidivism reduction programming or productive activities."],[3,"(ii) A prisoner determined by the Bureau of Prisons to be at a minimum or low risk for recidivating, who, over 2 consecutive assessments, has not increased their risk of recidivism, shall earn an additional 5 days of time credits for every 30 days of successful participation in evidence-based recidivism reduction programming or productive activities."],[2,"(B) Availability.—A prisoner may not earn time credits under this paragraph for an evidence-based recidivism reduction program that the prisoner successfully completed—"],[3,"(i) prior to the date of enactment of this subchapter; or"],[3,"(ii) during official detention prior to the date that the prisoner's sentence commences under section 3585(a)."],[2,"(C) Application of time credits toward prerelease custody or supervised release.—Time credits earned under this paragraph by prisoners who successfully participate in recidivism reduction programs or productive activities shall be applied toward time in prerelease custody or supervised release. The Director of the Bureau of Prisons shall transfer eligible prisoners, as determined under section 3624(g), into prerelease custody or supervised release."],[2,"(D) Ineligible prisoners.—A prisoner is ineligible to receive time credits under this paragraph if the prisoner is serving a sentence for a conviction under any of the following provisions of law:"],[3,"(i) Section 32, relating to destruction of aircraft or aircraft facilities."],[3,"(ii) Section 33, relating to destruction of motor vehicles or motor vehicle facilities."],[3,"(iii) Section 36, relating to drive-by shootings."],[3,"(iv) Section 81, relating to arson within special maritime and territorial jurisdiction."],[3,"(v) Section 111(b), relating to assaulting, resisting, or impeding certain officers or employees using a deadly or dangerous weapon or inflicting bodily injury."],[3,"(vi) Paragraph (1), (7), or (8) of section 113(a), relating to assault with intent to commit murder, assault resulting in substantial bodily injury to a spouse or intimate partner, a dating partner, or an individual who has not attained the age of 16 years, or assault of a spouse, intimate partner, or dating partner by strangling, suffocating, or attempting to strangle or suffocate."],[3,"(vii) Section 115, relating to influencing, impeding, or retaliating against a Federal official by injuring a family member, except for a threat made in violation of that section."],[3,"(viii) Section 116, relating to female genital mutilation."],[3,"(ix) Section 117, relating to domestic assault by a habitual offender."],[3,"(x) Any section of chapter 10, relating to biological weapons."],[3,"(xi) Any section of chapter 11B, relating to chemical weapons."],[3,"(xii) Section 351, relating to Congressional, Cabinet, and Supreme Court assassination, kidnapping, and assault."],[3,"(xiii) Section 521, relating to criminal street gangs."],[3,"(xiv) Section 751, relating to prisoners in custody of an institution or officer."],[3,"(xv) Section 793, relating to gathering, transmitting, or losing defense information."],[3,"(xvi) Section 794, relating to gathering or delivering defense information to aid a foreign government."],[3,"(xvii) Any section of chapter 39, relating to explosives and other dangerous articles, except for section 836 (relating to the transportation of fireworks into a State prohibiting sale or use)."],[3,"(xviii) Section 842(p), relating to distribution of information relating to explosives, destructive devices, and weapons of mass destruction, but only if the conviction involved a weapon of mass destruction (as defined in section 2332a(c))."],[3,"(xix) Subsection (f)(3), (h), or (i) of section 844, relating to the use of fire or an explosive."],[3,"(xx) Section 871, relating to threats against the President and successors to the Presidency."],[3,"(xxi) Section 879, relating to threats against former Presidents and certain other persons."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3632?type=usc&year=mostrecent&link-type=html"},"head":"§3632. Development of risk and needs assessment system","tname":"Crimes and Criminal Procedure","by":{"0":"9, 9, 10, 14, 9","1":"20, 20, 20, 20, 20","2":"18, 3, 17, 18"}},{"t":"usc","label":"18 U.S.C. § 3635","url":"https://www.law.cornell.edu/uscode/text/18/3635","subs":["(3)","(5)","(3)(C)(iii)","(3)(C)(v)","(3)(C)(ix)"],"stext":{"head":"§3635. Definitions","paras":[[0,"In this subchapter the following definitions apply:"],[1,"(1) Dyslexia.—The term \"dyslexia\" means an unexpected difficulty in reading for an individual who has the intelligence to be a much better reader, most commonly caused by a difficulty in the phonological processing (the appreciation of the individual sounds of spoken language), which affects the ability of an individual to speak, read, and spell."],[1,"(2) Dyslexia screening program.—The term \"dyslexia screening program\" means a screening program for dyslexia that is—"],[2,"(A) evidence-based (as defined in section 8101(21) of the Elementary and Secondary Education Act of 1965 (20 U.S.C. 7801(21))) with proven psychometrics for validity;"],[2,"(B) efficient and low-cost; and"],[2,"(C) readily available."],[1,"(3) Evidence-based recidivism reduction program.—The term \"evidence-based recidivism reduction program\" means either a group or individual activity that—"],[2,"(A) has been shown by empirical evidence to reduce recidivism or is based on research indicating that it is likely to be effective in reducing recidivism;"],[2,"(B) is designed to help prisoners succeed in their communities upon release from prison; and"],[2,"(C) may include—"],[3,"(i) social learning and communication, interpersonal, anti-bullying, rejection response, and other life skills;"],[3,"(ii) family relationship building, structured parent-child interaction, and parenting skills;"],[3,"(iii) classes on morals or ethics;"],[3,"(iv) academic classes;"],[3,"(v) cognitive behavioral treatment;"],[3,"(vi) mentoring;"],[3,"(vii) substance abuse treatment;"],[3,"(viii) vocational training;"],[3,"(ix) faith-based classes or services;"],[3,"(x) civic engagement and reintegrative community services;"],[3,"(xi) a prison job, including through a prison work program;"],[3,"(xii) victim impact classes or other restorative justice programs; and"],[3,"(xiii) trauma counseling and trauma-informed support programs."],[1,"(4) Prisoner.—The term \"prisoner\" means a person who has been sentenced to a term of imprisonment pursuant to a conviction for a Federal criminal offense, or a person in the custody of the Bureau of Prisons."],[1,"(5) Productive activity.—The term \"productive activity\" means either a group or individual activity that is designed to allow prisoners determined as having a minimum or low risk of recidivating to remain productive and thereby maintain a minimum or low risk of recidivating, and may include the delivery of the programs described in paragraph (1) 1 to other prisoners."],[1,"(6) Risk and needs assessment tool.—The term \"risk and needs assessment tool\" means an objective and statistically validated method through which information is collected and evaluated to determine—"],[2,"(A) as part of the intake process, the risk that a prisoner will recidivate upon release from prison;"],[2,"(B) the recidivism reduction programs that will best minimize the risk that the prisoner will recidivate upon release from prison; and"],[2,"(C) the periodic reassessment of risk that a prisoner will recidivate upon release from prison, based on factors including indicators of progress and of regression, that are dynamic and that can reasonably be expected to change while in prison."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3635?type=usc&year=mostrecent&link-type=html"},"head":"§3635. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"10, 10","1":"20, 20, 20"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/28/1361","stext":{"head":"§1361. Action to compel an officer of the United States to perform his duty","paras":[[0,"The district courts shall have original jurisdiction of any action in the nature of mandamus to compel an officer or employee of the United States or any agency thereof to perform a duty owed to the plaintiff."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1361?type=usc&year=mostrecent&link-type=html"},"head":"§1361. Action to compel an officer of the United States to perform his duty","tname":"Judiciary and Judicial Procedure","by":{"0":"31","1":"20"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","subs":["(e)(1)"],"by":{"0":"33"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(1994)","(a)","(c)","(c)(3)"],"stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"head":"§2241. Power to grant writ","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 2, 7, 10-12, 4, 16, 19, 4, 16","1":"18, 22","2":"4, 5, 9"}},{"t":"usc","label":"28 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/28/2243","subs":["(1994)"],"stext":{"head":"§2243. Issuance of writ; return; hearing; decision","paras":[[0,"A court, justice or judge entertaining an application for a writ of habeas corpus shall forthwith award the writ or issue an order directing the respondent to show cause why the writ should not be granted, unless it appears from the application that the applicant or person detained is not entitled thereto."],[0,"The writ, or order to show cause shall be directed to the person having custody of the person detained. It shall be returned within three days unless for good cause additional time, not exceeding twenty days, is allowed."],[0,"The person to whom the writ or order is directed shall make a return certifying the true cause of the detention."],[0,"When the writ or order is returned a day shall be set for hearing, not more than five days after the return unless for good cause additional time is allowed."],[0,"Unless the application for the writ and the return present only issues of law the person to whom the writ is directed shall be required to produce at the hearing the body of the person detained."],[0,"The applicant or the person detained may, under oath, deny any of the facts set forth in the return or allege any other material facts."],[0,"The return and all suggestions made against it may be amended, by leave of court, before or after being filed."],[0,"The court shall summarily hear and determine the facts, and dispose of the matter as law and justice require."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2243?type=usc&year=mostrecent&link-type=html"},"head":"§2243. Issuance of writ; return; hearing; decision","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 2, 4, 7, 12, 16-19, 24","1":"18, 22","2":"4"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)","(d)(1)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 32, 33","1":"18"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(1994)","(b)","(d)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 32, 7, 33","1":"22","2":"15"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(1994)","(a)","(e)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 3, 7, 16, 18, 24, 18, 12, 19, 27","1":"18, 18","2":"3, 5, 5"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"5, 14, 25-27, 30, 33","1":"28","2":"2, 8, 15"}},{"t":"case","label":"Albright v. Oliver","cite":"510 U.S. 266","y":1994,"id":"1993/92-833","sc":1,"sum":"The Court ruled that Section 1983 relief for prosecution without probable cause is only valid if the prosecuted party claims Fourth Amendment (pretrial rights) violations.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Anderson v. Corall","cite":"263 U.S. 193","y":1923,"id":"scdb/1923-028","sc":1,"sum":"1. Mere lapse of time, without imprisonment or other restraint contemplated by law, does not constitute service of sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 27","2":"10"}},{"t":"case","label":"Baxter v. Bracey","cite":"590 U.S. 1011","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/1011/","sc":1,"by":{"1":"19"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 33"}},{"t":"case","label":"Carson v. Johnson","cite":"112 F.3d 818","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/818/","by":{"1":"33"}},{"t":"case","label":"Conway v. California Adult Auth.","cite":"396 U.S. 107","y":1969,"id":"1969/40","sc":1,"sum":"The writ of certiorari is dismissed as improvidently granted. Certiorari dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Cooper v. Pate","cite":"378 U.S. 546","y":1964,"id":"scdb/1963-172","sc":1,"sum":"Certiorari granted and judgment reversed. Reported below: 324 F. 2d 165. Alex Elson and Bernard Weisberg for petitioner. William G. Clark, Attorney General of Illinois, and Raymond S. Sarnow and Edward A. Berman, Assistant Attorneys General, for respondent.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/103/","sc":1,"by":{"1":"29, 39"}},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"sum":"Relying on Bivens v. Six Unknown Federal Narcotics Agents (1971) and Butz v. Economou (1978), the Court reversed the lower court's conclusions. Both cases affirmed a citizen's right to bring suit against federal officers for constitutional violations. In this case, Passman violated Davis's rights through sexual discrimination.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Dreyer v. Illinois","cite":"187 U.S. 71","y":1902,"id":"scdb/1902-031","sc":1,"sum":"Dveyer was convicted in a state court of Illinois for having failed to turn over, as required by statute, to bis successor in office, certain revenues, bonds, funds, warrants and personal property, that came into his hands as Treasurer of a Board of Public Park Commissioners. The judgment of conviction was affirmed by the Supreme Court of Illinois, and the accused was sentenced to the penitentiary.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"E.M.D. Sales, Inc. v. Carrera","cite":"604 U.S. 45","y":2025,"id":"2024/23-217","sc":1,"sum":"The preponderance-of-the-evidence standard applies when an employer seeks to demonstrate that an employee is exempt from the minimum-wage and overtime-pay provisions of the Fair Labor Standards Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40","2":"16"}},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17, 19"}},{"t":"case","label":"Esteras v. United States","cite":"606 U.S. 185","y":2025,"id":"2024/23-7483","sc":1,"sum":"A district court considering whether to revoke a defendant’s term of supervised release may not consider 18 U. S. C. §3553(a)(2)(A), which covers retribution vis-à-vis the defendant’s underlying criminal offense.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"7, 38"}},{"t":"case","label":"Graham v. Broglin","cite":"922 F.2d 379","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/922/379/","sum":"Stating that a claim seeking transfer from solitary confinement to the prison’s general population would lie in habeas.","sumSrc":"brief:1","by":{"1":"24, 26","2":"6"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Hernández v. Mesa","cite":"589 U.S. 93","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/93/","sc":1,"by":{"1":"33"}},{"t":"case","label":"Hewitt v. United States","cite":"606 U.S. 419","y":2025,"id":"2024/23-1002","sc":1,"sum":"Because a sentence “has . . . been imposed” for purposes of §403(b) of the First Step Act only if the sentence is extant (i.e., has not been vacated), the Act’s more lenient penalties apply to defendants whose previous 18 U. S. C. §924(c) sentences have been vacated and who need to be resentenced following the Act’s enactment; the judgment of the Fifth Circuit is reversed and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"8"}},{"t":"case","label":"Ingram v. SCI Smithfield","cite":"2023 WL 110588","y":2023,"court":"3d Cir. Jan. 5","by":{"1":"34"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"1":"7","2":"10"}},{"t":"case","label":"Kansas v. Garcia","cite":"589 U.S. 191","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"McInnis v. Strand","cite":"2008 WL 2206712","y":2008,"court":"D.N.D. May 27","by":{"1":"34"}},{"t":"case","label":"McKune v. Lile","cite":"536 U.S. 24","y":2002,"id":"2001/00-1187","sc":1,"sum":"Joined by Chief Justice William H. Rehnquist and Justice Antonin Scalia, the Court held that the SATP serves a vital penological purpose, and that offering inmates minimal incentives to participate does not amount to compelled self-incrimination prohibited by the Fifth Amendment.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"ar":1,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"1":"30, 31"}},{"t":"case","label":"Muhammad v. Close","cite":"540 U.S. 749","y":2004,"id":"2003/02-9065","sc":1,"sum":"In a unanimous per curiam opinion, the Court ruled that prisoners - whose suits do not question their sentences - do not need to successfully challenge those sentences before challenging prison disciplinary proceedings. The Court rejected the argument that Heck necessarily requires successful sentence appeals before any challenges can be made to prison disciplinary proceedings.","sumSrc":"Oyez","by":{"1":"21, 22","2":"8, 15"}},{"t":"case","label":"Mullin v. Doe","cite":"146 S. Ct. 2121","y":2026,"id":"2025/25-1083","sc":1,"sum":"Section 1254a(b)(5)(A) bars judicial review of non-constitutional claims related to Temporary Protected Status (TPS); Miot respondents’ equal protection claim—that Haiti’s TPS designation was terminated because of race—is unlikely to succeed because a race-neutral explanation for the Government’s action exists: the current administration opposes the TPS program as it has been implemented in the past and has terminated every TPS designation that has come up for renewal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"1":"38"}},{"t":"case","label":"Nettles v. Grounds","cite":"830 F.3d 922","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/830/922/","by":{"1":"36","2":"7"}},{"t":"case","label":"Osorio-Calderon v. Warden","cite":"179 F.4th 1158","y":2026,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/179/1158/","ar":1,"by":{"1":"39, 40"}},{"t":"case","label":"People v. Santos","cite":"298 N.Y.S.2d 526","y":1969,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/298/526/","by":{"1":"28"}},{"t":"case","label":"Perttu v. Richards","cite":"605 U.S. 460","y":2025,"id":"2024/23-1324","sc":1,"ar":1,"sum":"Parties are entitled to a jury trial on the issue of exhaustion of remedies under The Prison Litigation Reform Act when that issue is intertwined with the merits of a claim that requires a jury trial under the Seventh Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16, 20","2":"19"}},{"t":"case","label":"Piccarillo v. New York State Bd. of Parole","cite":"397 N.E.2d 354","y":1979,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/397/354/","by":{"1":"28"}},{"t":"case","label":"Porter v. Nussle","cite":"534 U.S. 516","y":2002,"id":"2001/00-853","sc":1,"sum":"The Court held that the PLRA's exhaustion requirement applies to all inmate suits about prison life, whether they involve general circumstances or particular episodes, and whether they allege excessive force or some other wrong. The Court rejected Nussle's argument that Congress added the words \"prison conditions\" to exempt excessive force claims.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27","2":"12"}},{"t":"case","label":"Sanchez v. Miller","cite":"792 F.2d 694","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/694/","by":{"1":"35"}},{"t":"case","label":"Samson v. California","cite":"547 U.S. 843","y":2006,"id":"2005/04-9728","sc":1,"sum":"In a 6-to-3 decision authored by Justice Clarence Thomas, the Supreme Court held that Samson \"did not have an expectation of privacy that society would recognize as legitimate.\" Parole allows convicted criminals out of prison before their sentence is completed.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"sum":"To prevail under 42 U. S. C. §12112(a), a plaintiff must plead and prove that she held or desired a job, and could perform its essential functions with or without reasonable accommodation, at the time of an employer’s alleged act of disability-based discrimination; the judgment of the Eleventh Circuit is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Sylvester v. Hanks","cite":"140 F.3d 713","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/140/713/","by":{"1":"26"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Touzier v. United States Att’y Gen.","cite":"2021 WL 3829618","y":2021,"court":"11th Cir. Aug. 27","by":{"1":"39"}},{"t":"case","label":"Trainmen v. Toledo, Peoria & W. R.R.","cite":"321 U.S. 50","y":1944,"id":"scdb/1943-097","sc":1,"sum":"1. A railroad company which refused to submit a labor dispute to arbitration in accordance with provisions of the Railway Labor Act-although it had sought to settle the dispute by negotiation and by mediation-has not made \"every reasonable effort\" to settle the dispute, within the meaning of §8 of the Norris-LaGuardia Act, and is thereby barred from injunctive relief in the federal courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Ughbanks v. Armstrong","cite":"208 U.S. 481","y":1908,"id":"scdb/1907-090","sc":1,"sum":"The indeterminate sentence law of Michigan of 1903, as. construed and sustained according to its own constitution, by the highest court of that State, does not violate any provision of the Federal Constitution. It is of a character similar to the Illinois act, sustained by this court in Dreyér v. Illinois, 187 Ü. S. 71.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"United States v. Anderson","cite":"583 F.3d 504","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/583/504/","by":{"1":"31"}},{"t":"case","label":"United States v. Earl","cite":"729 F.3d 1064","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/1064/","by":{"1":"27"}},{"t":"case","label":"United States v. Holt","cite":"116 F.4th 599","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/116/599/","by":{"1":"21"}},{"t":"case","label":"United States v. Latimer","cite":"991 F.2d 1509","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/991/1509/","sum":"Noting the Sentencing Commission’s view that “confinement in a community treatment center [i]s qualitatively different from a sentence of imprisonment”.","sumSrc":"brief:1","by":{"1":"31"}},{"t":"case","label":"United States v. Muniz","cite":"374 U.S. 150","y":1963,"id":"1962/464","sc":1,"sum":"A federal prisoner can sue under the Federal Tort Claims Act to recover damages from the United States for personal injuries sustained during confinement in a federal prison and resulting from the negligence of a government employee. Feres v. United States. 340 U. S. 135, distinguished. Pp. 150-166. 305 F. 2d 253, 285, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"United States v. Price","cite":"84 F.4th 738","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/84/738/","by":{"1":"5"}},{"t":"case","label":"United States v. Sack","cite":"379 F.3d 1177","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/379/1177/","sum":"Holding that abscondment from a halfway house violates the federal escape statute, 18 U.S.C. 751.","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"Upper Skagit Indian Tribe v. Lundgren","cite":"584 U.S. 554","y":2018,"id":"2017/17-387","sc":1,"sum":"The Court held that its prior decision in County of Yakima v. Confederated Tribes and Bands of Yakima Nation addressed only a question of statutory interpretation, not the question whether Indian tribes have sovereign immunity in rem lawsuits.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Warden v. Marrero","cite":"417 U.S. 653","y":1974,"id":"1973/73-831","sc":1,"sum":"The Comprehensive Drug Abuse Prevention and Control Act of 1970, which became effective May 1, 1971, makes parole under the general parole statute, 18 U. S. C. § 4202, available for almost all narcotics offenders. Respondent, who had been sentenced before May 1, 1971, and was ineligible for parole under 26 U. S. C. § 7237 (d), which was repealed by the 1970 Act, sought habeas corpus in the District Court, claiming …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"ar":1,"sum":"The Supreme Court held that while prisoners are not entitled to full due process protections, disciplinary proceedings must include written notice to the defendant of the charges, a written statement of evidence, and the opportunity for an inmate to call witnesses and present evidence.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Young v. Harper","cite":"520 U.S. 143","y":1997,"id":"1996/95-1598","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that Oklahoma's Preparole Conditional Supervision Program, as it existed when Leroy L. Young was released, was equivalent to parole and therefore he was entitle to procedural due process safeguards.","sumSrc":"Oyez","by":{"1":"32","2":"13"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"1":"36"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"21"}},{"t":"law","label":"Coronavirus Aid, Relief, and Economic Security Act, Pub. L. No. 116-136","url":"https://www.govinfo.gov/link/plaw/116/public/136","by":{"1":"12"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)","(b)(1)"],"by":{"1":"20, 34"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"1":"20, 20","2":"15"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(d)"],"by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 110-199","url":"https://www.govinfo.gov/link/plaw/110/public/199","by":{"1":"6"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"3, 4"}},{"t":"usc","label":"18 U.S.C. § 751","url":"https://www.law.cornell.edu/uscode/text/18/751","by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(d)(1)","(d)(1)(2006)"],"by":{"1":"11, 4"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(k)"],"by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(h)"],"by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","subs":["(c)(1)(B)(i)"],"by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)"],"by":{"1":"7"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(a)","(b)","(b)(1)","(b)(4)(B)","(c)","(g)(2)","(g)(4)","(h)(5)(C)(iv)"],"stext":{"head":"§3621. Imprisonment of a convicted person","paras":[[0,"(a) Commitment to Custody of Bureau of Prisons.—A person who has been sentenced to a term of imprisonment pursuant to the provisions of subchapter D of chapter 227 shall be committed to the custody of the Bureau of Prisons until the expiration of the term imposed, or until earlier released for satisfactory behavior pursuant to the provisions of section 3624."],[0,"(b) Place of Imprisonment.—The Bureau of Prisons shall designate the place of the prisoner's imprisonment, and shall, subject to bed availability, the prisoner's security designation, the prisoner's programmatic needs, the prisoner's mental and medical health needs, any request made by the prisoner related to faith-based needs, recommendations of the sentencing court, and other security concerns of the Bureau of Prisons, place the prisoner in a facility as close as practicable to the prisoner's primary residence, and to the extent practicable, in a facility within 500 driving miles of that residence. The Bureau shall, subject to consideration of the factors described in the preceding sentence and the prisoner's preference for staying at his or her current facility or being transferred, transfer prisoners to facilities that are closer to the prisoner's primary residence even if the prisoner is already in a facility within 500 driving miles of that residence. The Bureau may designate any available penal or correctional facility that meets minimum standards of health and habitability established by the Bureau, whether maintained by the Federal Government or otherwise and whether within or without the judicial district in which the person was convicted, that the Bureau determines to be appropriate and suitable, considering—"],[1,"(1) the resources of the facility contemplated;"],[1,"(2) the nature and circumstances of the offense;"],[1,"(3) the history and characteristics of the prisoner;"],[1,"(4) any statement by the court that imposed the sentence—"],[2,"(A) concerning the purposes for which the sentence to imprisonment was determined to be warranted; or"],[2,"(B) recommending a type of penal or correctional facility as appropriate; and"],[1,"(5) any pertinent policy statement issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28."],[0,"In designating the place of imprisonment or making transfers under this subsection, there shall be no favoritism given to prisoners of high social or economic status. The Bureau may at any time, having regard for the same matters, direct the transfer of a prisoner from one penal or correctional facility to another. The Bureau shall make available appropriate substance abuse treatment for each prisoner the Bureau determines has a treatable condition of substance addiction or abuse. Any order, recommendation, or request by a sentencing court that a convicted person serve a term of imprisonment in a community corrections facility shall have no binding effect on the authority of the Bureau under this section to determine or change the place of imprisonment of that person. Notwithstanding any other provision of law, a designation of a place of imprisonment under this subsection is not reviewable by any court."],[0,"(c) Delivery of Order of Commitment.—When a prisoner, pursuant to a court order, is placed in the custody of a person in charge of a penal or correctional facility, a copy of the order shall be delivered to such person as evidence of this authority to hold the prisoner, and the original order, with the return endorsed thereon, shall be returned to the court that issued it."],[0,"(d) Delivery of Prisoner for Court Appearances.—The United States marshal shall, without charge, bring a prisoner into court or return him to a prison facility on order of a court of the United States or on written request of an attorney for the Government."],[0,"(e) Substance Abuse Treatment.—"],[1,"(1) Phase-in.—In order to carry out the requirement of the last sentence of subsection (b) of this section, that every prisoner with a substance abuse problem have the opportunity to participate in appropriate substance abuse treatment, the Bureau of Prisons shall, subject to the availability of appropriations, provide residential substance abuse treatment (and make arrangements for appropriate aftercare)—"],[2,"(A) for not less than 50 percent of eligible prisoners by the end of fiscal year 1995, with priority for such treatment accorded based on an eligible prisoner's proximity to release date;"],[2,"(B) for not less than 75 percent of eligible prisoners by the end of fiscal year 1996, with priority for such treatment accorded based on an eligible prisoner's proximity to release date; and"],[2,"(C) for all eligible prisoners by the end of fiscal year 1997 and thereafter, with priority for such treatment accorded based on an eligible prisoner's proximity to release date."],[1,"(2) Incentive for prisoners' successful completion of treatment program.—"],[2,"(A) Generally.—Any prisoner who, in the judgment of the Director of the Bureau of Prisons, has successfully completed a program of residential substance abuse treatment provided under paragraph (1) of this subsection, shall remain in the custody of the Bureau under such conditions as the Bureau deems appropriate. If the conditions of confinement are different from those the prisoner would have experienced absent the successful completion of the treatment, the Bureau shall periodically test the prisoner for substance abuse and discontinue such conditions on determining that substance abuse has recurred."],[2,"(B) Period of custody.—The period a prisoner convicted of a nonviolent offense remains in custody after successfully completing a treatment program may be reduced by the Bureau of Prisons, but such reduction may not be more than one year from the term the prisoner must otherwise serve."],[1,"(3) Report.—The Bureau of Prisons shall transmit to the Committees on the Judiciary of the Senate and the House of Representatives on January 1, 1995, and on January 1 of each year thereafter, a report. Such report shall contain—"],[2,"(A) a detailed quantitative and qualitative description of each substance abuse treatment program, residential or not, operated by the Bureau;"],[2,"(B) a full explanation of how eligibility for such programs is determined, with complete information on what proportion of prisoners with substance abuse problems are eligible; and"],[2,"(C) a complete statement of to what extent the Bureau has achieved compliance with the requirements of this title."],[1,"(4) Authorization of appropriations.—There are authorized to carry out this subsection such sums as may be necessary for each of fiscal years 2007 through 2011."],[1,"(5) Definitions.—As used in this subsection—"],[2,"(A) the term \"residential substance abuse treatment\" means a course of individual and group activities and treatment, lasting at least 6 months, in residential treatment facilities set apart from the general prison population (which may include the use of pharmocotherapies,1 where appropriate, that may extend beyond the 6-month period);"],[2,"(B) the term \"eligible prisoner\" means a prisoner who is—"],[3,"(i) determined by the Bureau of Prisons to have a substance abuse problem; and"],[3,"(ii) willing to participate in a residential substance abuse treatment program; and"],[2,"(C) the term \"aftercare\" means placement, case management and monitoring of the participant in a community-based substance abuse treatment program when the participant leaves the custody of the Bureau of Prisons."],[1,"(6) Coordination of federal assistance.—The Bureau of Prisons shall consult with the Department of Health and Human Services concerning substance abuse treatment and related services and the incorporation of applicable components of existing comprehensive approaches including relapse prevention and aftercare services."],[1,"(7) Eligibility of primary caretaker parents and pregnant women.—The Director of the Bureau of Prisons may not prohibit an eligible prisoner who is a primary caretaker parent (as defined in section 4051) or pregnant from participating in a program of residential substance abuse treatment provided under paragraph (1) on the basis of a failure by the eligible prisoner, before being committed to the custody of the Bureau of Prisons, to disclose to any official of the Bureau of Prisons that the prisoner had a substance abuse problem on or before the date on which the eligible prisoner was committed to the custody of the Bureau of Prisons."],[0,"(f) Sex Offender Management.—"],[1,"(1) In general.—The Bureau of Prisons shall make available appropriate treatment to sex offenders who are in need of and suitable for treatment, as follows:"],[2,"(A) Sex offender management programs.—The Bureau of Prisons shall establish non-residential sex offender management programs to provide appropriate treatment, monitoring, and supervision of sex offenders and to provide aftercare during pre-release custody."],[2,"(B) Residential sex offender treatment programs.—The Bureau of Prisons shall establish residential sex offender treatment programs to provide treatment to sex offenders who volunteer for such programs and are deemed by the Bureau of Prisons to be in need of and suitable for residential treatment."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3621?type=usc&year=mostrecent&link-type=html"},"head":"§3621. Imprisonment of a convicted person","tname":"Crimes and Criminal Procedure","by":{"1":"6, 34, 37, 37, 37, 37, 37, 20, 29","2":"3, 11, 15-19, 10"}},{"t":"case","label":"Adepoju v. Scales","cite":"782 F. Supp. 3d 306","y":2025,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/782/306/","by":{"2":"17"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"sum":"The Court held that a covenant not to sue invalidates a company’s counterclaim for trademark enforcement.","sumSrc":"Oyez","by":{"2":"20, 21"}},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"sum":"The Court held that a federal court can recharacterize a motion as a first habeas corpus petition only if the court: (1) informs the litigant of the court's intent to recharacterize; (2) warns the litigant that this recharacterization means that any subsequent habeas corpus petition will be treated as a second petition; (3) gives the litigant an opportunity to withdraw or amend the motion.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Chafin v. Chafin","cite":"568 U.S. 165","y":2013,"id":"2012/11-1347","sc":1,"ar":2,"sum":"The Court decided that the return of a child to his or her country of residence pursuant to The Hague Convention, does not make an appeal of that order moot.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Chatrie v. United States","cite":"609 U.S. 605","y":2026,"id":"2025/25-112","sc":1,"sum":"Police officers conducted a Fourth Amendment search when they acquired Okello Chatrie’s location data from Google because an individual has a reasonable expectation of privacy in his cell-phone location information.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"19"}},{"t":"case","label":"Cooper Industries, Inc. v. Aviall Services, Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Gonzalez v. Herrera","cite":"151 F.4th 1076","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/151/1076/","by":{"2":"20, 21"}},{"t":"case","label":"Haines v. Kerner","cite":"404 U.S. 519","y":1972,"id":"1971/70-5025","sc":1,"sum":"The Court held that a prisoner has the right to submit proof of his alleged injuries before his case is dismissed.","sumSrc":"Oyez","by":{"2":"8, 15"}},{"t":"case","label":"(I) Cases—continued: INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Meachum v. Fano","cite":"427 U.S. 215","y":1976,"id":"1975/75-252","sc":1,"ar":2,"sum":"The Due Process Clause of the Fourteenth Amendment held not to entitle a duly convicted state prisoner to a factfinding hearing when he is transferred to a prison the conditions of which are substantially less favorable to him, absent a state law or practice conditioning such transfers on proof of serious misconduct or the occurrence of other specified events. Such a transfer does not infringe or implicate a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Ramsey v. Brennan","cite":"878 F.2d 995","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/878/995/","by":{"2":"12"}},{"t":"case","label":"Sinochem International Co. v. Malaysia International Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"ar":1,"sum":"The Court ruled 9-0 that \"a court need not resolve whether it has [...] personal jurisdiction over the defendant if it determines that [...] a foreign tribunal is plainly the more suitable arbiter of the merits of the case.\" The opinion by Justice Ruth Bader Ginsburg held that while the first step of a court is normally to determine whether it has jurisdiction, a court can dismiss a case for forum non conveniens without establishing subject-matter or personal jurisdiction.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Wales v. Whitney","cite":"114 U.S. 564","y":1885,"id":"scdb/1884-238","sc":1,"sum":"The act of March 3, 1885, Laws 2d Sess. 48th Cong. ch. 353, page 437, restored to this court appellate jurisdiction in habeas corpus cases over decisions of Circuit Courts of the United States and decisions of the Supreme Court of the District of Columbia.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Warner Chappell Music, Inc. v. Nealy","cite":"601 U.S. 366","y":2024,"id":"2023/22-1078","sc":1,"sum":"The Copyright Act entitles a copyright owner to obtain monetary relief for any timely infringement claim, no matter when the infringement occurred.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"19"}},{"t":"case","label":"West Virginia v. B. P. J.","cite":"146 S. Ct. 2356","y":2026,"id":"2025/24-43","sc":1,"sum":"Title IX allows schools to provide separate women’s and men’s sports teams defined by biological sex; West Virginia and Idaho did not violate the Equal Protection Clause of the Fourteenth Amendment by maintaining female sports teams for biological females.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"case","label":"Wright v. Cuyler","cite":"624 F.2d 455","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/624/455/","by":{"2":"6"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1761","url":"https://www.law.cornell.edu/uscode/text/18/1761","subs":["(a)"],"by":{"2":"10"}},{"t":"usc","label":"18 U.S.C. § 3585","url":"https://www.law.cornell.edu/uscode/text/18/3585","subs":["(b)"],"by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(b)"],"by":{"2":"10"}},{"t":"usc","label":"18 U.S.C. § 4202","url":"https://www.law.cornell.edu/uscode/text/18/4202","subs":["(1982)"],"by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","subs":["(1982)"],"by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 4209","url":"https://www.law.cornell.edu/uscode/text/18/4209","subs":["(1982)"],"by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 4214","url":"https://www.law.cornell.edu/uscode/text/18/4214","subs":["(1982)"],"by":{"2":"13"}},{"t":"reg","label":"28 C.F.R. § 2.52","url":"https://www.ecfr.gov/current/title-28/section-2.52","by":{"2":"13"}}]};